   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --card: #ffffff;
       --text: #132238;
       --muted: #5f6b7a;
       --border: #dbe4f0;
       --accent: #2563eb;
       --accent-soft: #eaf1ff;
       --shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       display: grid;
       place-items: center;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, #ffffff 0%, var(--bg) 55%);
       color: var(--text);
       padding: 24px;
     }

     .card {
       width: min(100%, 560px);
       background: var(--card);
       border: 1px solid rgba(219, 228, 240, 0.9);
       border-radius: 24px;
       box-shadow: var(--shadow);
       padding: 32px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       font-size: 0.875rem;
       font-weight: 600;
       color: var(--accent);
       background: var(--accent-soft);
       border-radius: 999px;
       padding: 8px 12px;
       margin-bottom: 16px;
     }

     h1 {
       margin: 0 0 8px;
       font-size: clamp(1.6rem, 2.5vw, 2.2rem);
       line-height: 1.15;
     }

     p {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.6;
     }

