       padding: 0;
       margin: 0 0 16px;
       font-size: 1rem;
       font-weight: 700;
     }

     .options {
       display: grid;
       gap: 12px;
     }

     .option {
       display: flex;
       align-items: center;
       gap: 12px;
       padding: 14px 16px;
       border: 1px solid var(--border);
       border-radius: 14px;
       background: #fff;
       cursor: pointer;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

