       appearance: none;
       border: 0;
       border-radius: 12px;
       background: var(--accent);
       color: #fff;
       font: inherit;
       font-weight: 700;
       padding: 14px 20px;
       cursor: pointer;
       box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
       transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
