 <body>
   <main class="card">
     <div class="eyebrow">Preferences</div>
     <h1>Notification settings</h1>
     <p>Choose the single channel you prefer for receiving updates.</p>

     <form id="notification-form">
       <fieldset class="form-field">
         <legend>How do you prefer to receive notifications?</legend>
         <div class="options">
           <label class="option">
             <input type="radio" name="notification-preference" value="Email" required />
             <span>Email</span>
           </label>
           <label class="option">
             <input type="radio" name="notification-preference" value="SMS" />
             <span>SMS</span>
           </label>
           <label class="option">
             <input type="radio" name="notification-preference" value="Push Notifications" />
             <span>Push Notifications</span>
           </label>
         </div>
       </fieldset>

       <div class="actions">
         <button type="submit">Submit</button>
         <div class="status" id="status" aria-live="polite"></div>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById('notification-form');
     const status = document.getElementById('status');

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       const selected = form.querySelector('input[name="notification-preference"]:checked');

       if (!selected) {
         status.textContent = 'Please choose one notification preference.';
         status.dataset.state = 'error';
         return;
       }

       status.textContent = `Saved preference: ${selected.value}.`;
       status.dataset.state = 'success';
     });
   </script>
 </body>
